let incX = 0.1;       // X方向のノイズ増加量（CPU負荷軽減）
let incY = 0.1;       // Y方向のノイズ増加量（CPU負荷軽減）
let distance = 40;    // 波の間隔（描画する線の数を減らすため）
let wavesHeight = 800; // 波の高さ（ノイズ値をこの値を基にマッピング）

let looping = true;   // アニメーションのループフラグ
let frame = 0;        // フレーム数管理用

function setup() {
  createCanvas(windowWidth, windowHeight); // ウィンドウサイズに合わせたキャンバス作成
  background(0);                            // 背景色を黒に設定
  noiseDetail(2);                           // ノイズのディテールを最小限に
  frameRate(24);                            // フレームレートを24FPSに制限
  // 色モードをHSBに変更（色相: 0～360, 彩度: 0～100, 明度: 0～100, アルファ: 0～100）
  colorMode(HSB, 60, 100, 100, 100);
}

function draw() {
  let zOff = looping ? frameCount * 0.01 : frame * 0.01; // Z軸のノイズオフセット
  // 背景を半透明の黒で再描画（トレイル効果）
  background(0, 5);

  noFill();          // 塗りなし
  strokeWeight(3); // 線の太さを固定
  let yOff = 0;      // Y軸ノイズオフセット初期化

  for (let y = -wavesHeight; y < height + wavesHeight; y += distance) {
    let xOff = 0; // 各行ごとにX軸ノイズオフセットを初期化
    for (let x = -wavesHeight; x < width; x += distance) {
      let n = noise(xOff, yOff, zOff); // 3Dノイズの値を取得
      let value = map(n, 0, 1, -wavesHeight / 2, wavesHeight / 2); // ノイズ値を波の高さにマッピング

      // もともとの色相はノイズの値から0～360にマッピング
      let hueValue = map(n, 0, 1, 0, 360);
      // 赤系の色も出るように、計算した色相を赤 (hue = 0) に50%ブレンドする
      hueValue = lerp(hueValue, 0, 0.5);
      // 彩度と明度は最大に設定して、色を鮮やかにする
      stroke(hueValue, 100, 100);

      let y2 = y + value; // ノイズを反映したY座標
      let n2 = noise(xOff, yOff + incY, zOff); // 縦方向のノイズ
      let value2 = map(n2, 0, 1, -wavesHeight / 2, wavesHeight / 2);

      // 横線を描画（線がキャンバス内に収まる場合のみ）
      if (x + distance < width) {
        line(x, y2, x + distance, y2);
      }

      // 縦線を描画（線がキャンバス内に収まる場合のみ）
      if (y + distance < height) {
        line(x, y2, x, y2 + value2);
      }

      xOff += incX; // 次のX位置へ移るため、X軸ノイズオフセットを更新
    }
    yOff += incY; // 次の行へ移るため、Y軸ノイズオフセットを更新
  }
}


